() => {
  const s = document.querySelector('select');
  if (!s) return { ok: false, error: 'no select' };
  const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype, 'value').set;
  nativeSetter.call(s, 'ds_1786355089618');
  s.dispatchEvent(new Event('change', { bubbles: true }));
  return { ok: true, value: s.value, selectedText: s.options[s.selectedIndex]?.textContent };
}

async () => {
  const start = Date.now();
  const timeout = 60000;
  while (Date.now() - start < timeout) {
    const text = document.body.innerText;
    const done = text.includes('真实数据') || text.includes('演示数据') || text.includes('示例数据') || text.includes('查询失败') || text.includes('错误') || text.includes('失败') || text.includes('抱歉');
    const processing = text.includes('AI 正在解析') || text.includes('正在生成');
    if (done && !processing) {
      return { status: 'done', hasRealData: text.includes('真实数据'), hasDemo: text.includes('演示数据') || text.includes('示例数据'), elapsed: Date.now() - start };
    }
    await new Promise(r => setTimeout(r, 3000));
  }
  const text = document.body.innerText;
  return { status: 'timeout-60s', processing: text.includes('AI 正在解析'), hasRealData: text.includes('真实数据') };
}

() => {
  const all = Array.from(document.querySelectorAll('*'));
  const badge = all.find(el => el.children.length <= 3 && el.textContent && el.textContent.includes('真实数据：SQL 已在数据库中实际执行') && el.textContent.length < 80);
  let badgeInfo = null;
  if (badge) {
    const cs = getComputedStyle(badge);
    badgeInfo = { tag: badge.tagName, className: badge.className, color: cs.color, bg: cs.backgroundColor, borderColor: cs.borderColor, text: badge.textContent.trim() };
  }
  const amberDemo = all.filter(el => el.children.length === 0 && el.textContent && (el.textContent.includes('演示数据') || el.textContent.includes('示例数据'))).map(el => el.textContent.trim());
  const canvas = document.querySelectorAll('canvas').length;
  const svg = document.querySelectorAll('svg').length;
  return { badgeInfo, amberDemo, canvas, svg };
}

